50	+  // Compute subtotal/GST/total/deposit for a quote from its line items.
51	+  // Amounts are GST-INCLUSIVE: gst is the portion already inside the total.
52	+  function computeQuoteTotals(
53	+    lineItems: Array<{ lineTotalCents: number }>,
54	+    gstRegistered: boolean,
55	+    depositEnabled: boolean,
56	+    depositType?: string,
57	+    depositValue?: number,
58	+  ) {
59	+    const totalCents = lineItems.reduce((s, li) => s + li.lineTotalCents, 0);
60	+    const gstCents = gstRegistered ? Math.round(totalCents - totalCents / (1 + GST_RATE)) : 0;
61	+    const subtotalCents = totalCents - gstCents;
62	+    let depositCents: number | null = null;
63	+    if (depositEnabled && depositType && depositValue != null) {
64	+      depositCents = depositType === "percent"
65	+        ? Math.round(totalCents * (depositValue / 100))
66	+        : Math.min(depositValue, totalCents);
67	+    }
68	+    return { subtotalCents, gstCents, totalCents, depositCents };
69	+  }
